package com.lauzhack.twin.model

import kotlinx.serialization.json.Json
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

// content/assumptions.json (Dev C, generated by tools/assumptions.py) decodes into Assumptions and is usable by the engine.
class AssumptionsContractTest {

    private val json = Json { ignoreUnknownKeys = true }
    private val repoRoot: File = generateSequence(File("").absoluteFile) { it.parentFile }.first { File(it, "content").isDirectory }
    private val assumptions = json.decodeFromString<Assumptions>(File(repoRoot, "content/assumptions.json").readText())

    @Test
    fun caseProbabilitiesCoverEveryCaseAndAddUpToOne() {
        assertEquals(CaseType.entries.toSet(), assumptions.defaultCaseProbs.keys)
        assertEquals(1.0, assumptions.defaultCaseProbs.values.sum(), 1e-9)
        assertTrue(assumptions.defaultCaseProbs.values.all { it >= 0.0 })
    }

    @Test
    fun everyObjectiveHasAPenalty() {
        assertEquals(Objective.entries.toSet(), assumptions.objectivePenalties.keys)
        assertTrue(assumptions.objectivePenalties.values.all { it >= 0.0 })
    }

    @Test
    fun ratesAreAnnualFractions() {
        assertTrue(assumptions.financingRateAnnual in 0.0..0.5, "financingRateAnnual ${assumptions.financingRateAnnual}")
        assertTrue(assumptions.investmentReturnAnnual in -0.5..0.5, "investmentReturnAnnual ${assumptions.investmentReturnAnnual}")
    }

    @Test
    fun sensitivityRangesAreUsable() {
        assertTrue(assumptions.sensitivity.isNotEmpty())
        assertEquals(assumptions.sensitivity.size, assumptions.sensitivity.map { it.id }.toSet().size, "duplicate ids")
        for (p in assumptions.sensitivity) {
            assertTrue(p.low <= p.base && p.base <= p.high && p.low < p.high, "${p.id}: ${p.low} ${p.base} ${p.high}")
            assertTrue(!p.label[Lang.ES].isNullOrBlank() && !p.label[Lang.EN].isNullOrBlank(), "${p.id}: label in ES and EN")
        }
        assertTrue(assumptions.sourceNotes.isNotEmpty())
    }
}
